// Bunny Planner: single-file Cloudflare Worker (generated by scripts/bundle.mjs).
// Paste this whole file into the Worker's code editor in the Cloudflare dashboard.
// Optional: add a KV namespace binding named TASKS in Settings > Bindings so tasks persist.

// ---- tools.js ----
// Bunny Planner tools. Pure logic: no network, no framework, no storage code.
// Every result carries a `mood` so the bunny can react to REAL state.

const MAX_TASKS = 40;
const WORKDAY_MINUTES = 480; // more than 8h of work = overbooked
const MAX_PENDING = 6; // more than 6 open tasks = overbooked
const BREAK_MINUTES = 10;
const LATEST_END = 22 * 60; // plan should end before 22:00

const emptyState = () => ({ tasks: [], doneDates: [], nextId: 1 });

// ---------- helpers ----------
const localDate = (ctx) =>
  new Date(ctx.now() + (ctx.tzOffsetMinutes || 0) * 60000).toISOString().slice(0, 10);

const addDays = (dateStr, n) => {
  const d = new Date(dateStr + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
};

function streakOf(doneDates, today) {
  const set = new Set(doneDates);
  let day = set.has(today) ? today : addDays(today, -1);
  let n = 0;
  while (set.has(day)) {
    n++;
    day = addDays(day, -1);
  }
  return n;
}

const pendingOf = (s) => s.tasks.filter((t) => t.status === 'pending');
const hhmm = (m) => String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0');

const ok = (text, data) => ({
  content: [{ type: 'text', text }],
  structuredContent: data,
});
const fail = (text) => ({
  content: [{ type: 'text', text }],
  structuredContent: { error: text, mood: 'confused' },
  isError: true,
});

// Builds a sequential schedule and trims it until it fits the day.
function buildPlan(pending, startMin) {
  const sorted = [...pending].sort((a, b) => a.minutes - b.minutes || a.id - b.id); // quick wins first
  const schedule = [];
  let t = startMin;
  for (const task of sorted) {
    schedule.push({ id: task.id, title: task.title, minutes: task.minutes, start: hhmm(t), end: hhmm(t + task.minutes) });
    t += task.minutes + BREAK_MINUTES;
  }
  const totalMinutes = sorted.reduce((a, x) => a + x.minutes, 0);
  const endMin = schedule.length ? t - BREAK_MINUTES : startMin;
  const overbooked = totalMinutes > WORKDAY_MINUTES || endMin > LATEST_END || sorted.length > MAX_PENDING;

  // Suggest moving the longest tasks to tomorrow until the day fits.
  const moveIds = [];
  if (overbooked) {
    const byLength = [...sorted].sort((a, b) => b.minutes - a.minutes);
    let keep = [...sorted];
    for (const cand of byLength) {
      const total = keep.reduce((a, x) => a + x.minutes, 0);
      const end = startMin + total + BREAK_MINUTES * Math.max(0, keep.length - 1);
      if (total <= WORKDAY_MINUTES && end <= LATEST_END && keep.length <= MAX_PENDING) break;
      moveIds.push(cand.id);
      keep = keep.filter((x) => x.id !== cand.id);
    }
  }
  return { schedule, totalMinutes, overbooked, moveIds };
}

// ---------- tool definitions ----------
const TOOLS = [
  {
    name: 'add_task',
    title: 'Add a task',
    description: 'Add a task to the user\'s plan for today. Use when the user wants to remember or schedule something.',
    inputSchema: {
      type: 'object',
      properties: {
        title: { type: 'string', description: 'Short task name, max 120 characters' },
        minutes: { type: 'integer', minimum: 5, maximum: 480, description: 'Estimated minutes (default 30)' },
      },
      required: ['title'],
      additionalProperties: false,
    },
    annotations: { readOnlyHint: false, destructiveHint: false, idempotentHint: false, openWorldHint: false },
    run(args, s) {
      const title = typeof args.title === 'string' ? args.title.trim() : '';
      if (!title) return fail('A task needs a title.');
      if (title.length > 120) return fail('Task title is too long (max 120 characters).');
      let minutes = args.minutes === undefined ? 30 : args.minutes;
      if (!Number.isInteger(minutes) || minutes < 5 || minutes > 480) return fail('Minutes must be a whole number from 5 to 480.');
      if (s.tasks.length >= MAX_TASKS) s.tasks = pendingOf(s); // drop finished tasks to make room
      if (s.tasks.length >= MAX_TASKS) return fail('Too many open tasks. Finish or clear some first.');
      const task = { id: s.nextId++, title, minutes, status: 'pending' };
      s.tasks.push(task);
      const pending = pendingOf(s);
      const totalMinutes = pending.reduce((a, x) => a + x.minutes, 0);
      const overbooked = totalMinutes > WORKDAY_MINUTES || pending.length > MAX_PENDING;
      const mood = overbooked ? 'concerned' : 'happy';
      const text = overbooked
        ? `Added "${title}". That makes ${pending.length} open tasks (${totalMinutes} min), which is a lot for one day.`
        : `Added "${title}" (${minutes} min). ${pending.length} open task${pending.length === 1 ? '' : 's'} today.`;
      return ok(text, { task, openCount: pending.length, totalMinutes, overbooked, mood });
    },
  },
  {
    name: 'plan_day',
    title: 'Plan the day',
    description: 'Build a time-ordered schedule from open tasks and flag whether the day is overbooked.',
    inputSchema: {
      type: 'object',
      properties: { start: { type: 'string', pattern: '^([01]\\d|2[0-3]):[0-5]\\d$', description: 'Start time HH:MM (default 09:00)' } },
      additionalProperties: false,
    },
    annotations: { readOnlyHint: true, destructiveHint: false, idempotentHint: true, openWorldHint: false },
    run(args, s) {
      const start = args.start === undefined ? '09:00' : args.start;
      if (typeof start !== 'string' || !/^([01]\d|2[0-3]):[0-5]\d$/.test(start)) return fail('Start must look like 09:00.');
      const startMin = Number(start.slice(0, 2)) * 60 + Number(start.slice(3));
      const pending = pendingOf(s);
      if (!pending.length) {
        return ok('Your plan is empty. Add a task to begin.', { schedule: [], totalMinutes: 0, overbooked: false, moveIds: [], mood: 'encouraging' });
      }
      const p = buildPlan(pending, startMin);
      const mood = p.overbooked ? 'concerned' : 'encouraging';
      const lines = p.schedule.map((x) => `${x.start}-${x.end} ${x.title}`).join('; ');
      const text = p.overbooked
        ? `This day is overbooked. Consider moving ${p.moveIds.length} task${p.moveIds.length === 1 ? '' : 's'} to tomorrow. Schedule: ${lines}`
        : `Here is a plan that fits: ${lines}`;
      return ok(text, { ...p, mood });
    },
  },
  {
    name: 'complete_task',
    title: 'Complete a task',
    description: 'Mark an open task as done, by id or by words in its title. Updates the daily streak.',
    inputSchema: {
      type: 'object',
      properties: {
        id: { type: 'integer', description: 'Task id' },
        title: { type: 'string', description: 'Part of the task title' },
      },
      additionalProperties: false,
    },
    annotations: { readOnlyHint: false, destructiveHint: false, idempotentHint: true, openWorldHint: false },
    run(args, s, ctx) {
      const pending = pendingOf(s);
      let match;
      if (Number.isInteger(args.id)) {
        match = pending.filter((t) => t.id === args.id);
      } else if (typeof args.title === 'string' && args.title.trim()) {
        const q = args.title.trim().toLowerCase();
        match = pending.filter((t) => t.title.toLowerCase().includes(q));
      } else {
        return fail('Tell me which task: give an id or part of its title.');
      }
      if (match.length === 0) return fail('I could not find an open task like that.');
      if (match.length > 1) return fail('More than one task matches: ' + match.map((t) => `#${t.id} ${t.title}`).join(', ') + '. Please use the id.');
      const task = match[0];
      task.status = 'done';
      const today = localDate(ctx);
      if (!s.doneDates.includes(today)) s.doneDates.push(today);
      s.doneDates = s.doneDates.slice(-60);
      const streak = streakOf(s.doneDates, today);
      const openCount = pendingOf(s).length;
      const text = openCount
        ? `Done: "${task.title}". ${openCount} to go. Streak: ${streak} day${streak === 1 ? '' : 's'}.`
        : `Done: "${task.title}". Your day is clear! Streak: ${streak} day${streak === 1 ? '' : 's'}.`;
      return ok(text, { task, openCount, dayCleared: openCount === 0, streak, mood: 'celebrating' });
    },
  },
  {
    name: 'get_streak',
    title: 'Get streak',
    description: 'Report how many days in a row the user has completed at least one task.',
    inputSchema: { type: 'object', properties: {}, additionalProperties: false },
    annotations: { readOnlyHint: true, destructiveHint: false, idempotentHint: true, openWorldHint: false },
    run(_args, s, ctx) {
      const today = localDate(ctx);
      const streak = streakOf(s.doneDates, today);
      const doneToday = s.doneDates.includes(today);
      const openCount = pendingOf(s).length;
      let mood = 'encouraging';
      if (doneToday) mood = streak >= 3 ? 'celebrating' : 'happy';
      const text = streak === 0
        ? 'No streak yet. Finish one task today to start it.'
        : doneToday
          ? `Streak: ${streak} day${streak === 1 ? '' : 's'}. Nice work today!`
          : `Streak: ${streak} day${streak === 1 ? '' : 's'}. Finish one task today to keep it going.`;
      return ok(text, { streak, doneToday, openCount, mood });
    },
  },
];

const READ_ONLY = new Set(TOOLS.filter((t) => t.annotations.readOnlyHint).map((t) => t.name));

// ---- storage.js ----
// One tiny interface: load(sessionId) -> state, save(sessionId, state).
// Swap the adapter without touching tool logic.

class MemoryStore {
  constructor() {
    this.map = new Map();
  }
  async load(sid) {
    const v = this.map.get(sid);
    return v ? structuredClone(v) : emptyState();
  }
  async save(sid, state) {
    this.map.set(sid, structuredClone(state));
  }
}

// Cloudflare KV adapter. Free-plan facts (from Cloudflare docs, checked Oct 2026): 1,000 writes/day
// in total, 100,000 reads/day, and only 1 write per second to the same key. A multi-item "add a, b, c"
// does several quick writes to one key, so save() retries after a short pause. Reads can be briefly stale
// (eventual consistency). Data expires after 30 days so abandoned anonymous sessions clean themselves up.
class KVStore {
  constructor(kv, { ttlSeconds = 60 * 60 * 24 * 30, sleep = (ms) => new Promise((r) => setTimeout(r, ms)) } = {}) {
    this.kv = kv;
    this.ttl = ttlSeconds;
    this.sleep = sleep;
  }
  async load(sid) {
    const raw = await this.kv.get('s:' + sid);
    return raw ? JSON.parse(raw) : emptyState();
  }
  async save(sid, state) {
    const body = JSON.stringify(state);
    let lastErr;
    for (let attempt = 0; attempt < 3; attempt++) {
      try {
        await this.kv.put('s:' + sid, body, { expirationTtl: this.ttl });
        return;
      } catch (e) {
        lastErr = e;
        if (attempt < 2) await this.sleep(1100);
      }
    }
    throw lastErr;
  }
}

// ---- mcp.js ----
// Minimal, dependency-free MCP server over Streamable HTTP (stateless, JSON responses).
// Uses only web-standard Request/Response, so the same code runs on Cloudflare Workers and Node 18+.

const SERVER_VERSION = '0.1.0';
const LATEST_PROTOCOL = '2025-11-25';
const SUPPORTED = ['2025-11-25', '2025-06-18', '2025-03-26'];

class RpcError extends Error {
  constructor(code, message) {
    super(message);
    this.code = code;
  }
}

const rpcResult = (id, result) => ({ jsonrpc: '2.0', id, result });
const rpcError = (id, code, message) => ({ jsonrpc: '2.0', id, error: { code, message } });

// Anonymous session + timezone from request headers (shared by /mcp and /chat).
function sessionInfo(request) {
  const sidRaw = request.headers.get('x-session-id') || '';
  const tzRaw = parseInt(request.headers.get('x-tz-offset-minutes') || '0', 10);
  return {
    sid: /^[A-Za-z0-9_-]{8,64}$/.test(sidRaw) ? sidRaw : 'demo',
    tzOffsetMinutes: Number.isFinite(tzRaw) ? Math.max(-840, Math.min(840, tzRaw)) : 0,
  };
}

function corsHeaders(request, env) {
  const origin = request.headers.get('origin');
  const h = {
    'access-control-allow-methods': 'POST, OPTIONS',
    'access-control-allow-headers': 'content-type, accept, mcp-protocol-version, mcp-session-id, x-session-id, x-tz-offset-minutes',
    'access-control-max-age': '86400',
    vary: 'origin',
  };
  if (origin) h['access-control-allow-origin'] = origin;
  return h;
}

// If ALLOWED_ORIGINS is set (comma separated), browser requests from other origins are refused.
function originAllowed(request, env) {
  const origin = request.headers.get('origin');
  const list = (env && env.ALLOWED_ORIGINS ? String(env.ALLOWED_ORIGINS) : '').split(',').map((x) => x.trim()).filter(Boolean);
  if (!origin || list.length === 0 || list.includes('*')) return true;
  return list.includes(origin);
}

function createMcp({ store, now = () => Date.now() }) {
  async function dispatch(msg, ctx) {
    switch (msg.method) {
      case 'initialize': {
        const asked = msg.params && msg.params.protocolVersion;
        return {
          protocolVersion: SUPPORTED.includes(asked) ? asked : LATEST_PROTOCOL,
          capabilities: { tools: { listChanged: false } },
          serverInfo: { name: 'bunny-planner', title: 'Bunny Planner', version: SERVER_VERSION },
          instructions:
            'Daily planning tools. Every tool result includes a "mood" (happy, concerned, encouraging, celebrating, confused) for a companion character.',
        };
      }
      case 'ping':
        return {};
      case 'tools/list':
        return {
          tools: TOOLS.map(({ name, title, description, inputSchema, annotations }) => ({ name, title, description, inputSchema, annotations })),
        };
      case 'tools/call': {
        const p = msg.params || {};
        const tool = TOOLS.find((t) => t.name === p.name);
        if (!tool) throw new RpcError(-32602, 'Unknown tool: ' + String(p.name));
        const args = p.arguments && typeof p.arguments === 'object' && !Array.isArray(p.arguments) ? p.arguments : {};
        const state = await store.load(ctx.sid);
        const result = tool.run(args, state, ctx);
        if (!READ_ONLY.has(tool.name) && !result.isError) await store.save(ctx.sid, state);
        return result;
      }
      default:
        throw new RpcError(-32601, 'Method not found: ' + msg.method);
    }
  }

  return async function handle(request, env = {}) {
    const cors = corsHeaders(request, env);
    const json = (body, status = 200) =>
      new Response(JSON.stringify(body), { status, headers: { 'content-type': 'application/json', ...cors } });

    if (!originAllowed(request, env)) return new Response('Forbidden origin', { status: 403 });
    if (request.method === 'OPTIONS') return new Response(null, { status: 204, headers: cors });
    if (request.method !== 'POST') {
      return new Response('Method Not Allowed', { status: 405, headers: { allow: 'POST, OPTIONS', ...cors } });
    }

    const ver = request.headers.get('mcp-protocol-version');
    if (ver && !SUPPORTED.includes(ver)) return json(rpcError(null, -32600, 'Unsupported MCP-Protocol-Version: ' + ver), 400);

    let msg;
    try {
      msg = JSON.parse(await request.text());
    } catch {
      return json(rpcError(null, -32700, 'Parse error'), 400);
    }
    if (Array.isArray(msg)) return json(rpcError(null, -32600, 'JSON-RPC batching is not supported'), 400);
    if (!msg || typeof msg !== 'object' || msg.jsonrpc !== '2.0') return json(rpcError(null, -32600, 'Invalid Request'), 400);

    // Notifications (no id) and client responses (no method): accept and return 202 with no body.
    if (typeof msg.method !== 'string' || msg.id === undefined || msg.id === null) {
      return new Response(null, { status: 202, headers: cors });
    }

    const ctx = { ...sessionInfo(request), now };

    try {
      return json(rpcResult(msg.id, await dispatch(msg, ctx)));
    } catch (e) {
      if (e instanceof RpcError) return json(rpcError(msg.id, e.code, e.message));
      return json(rpcError(msg.id, -32603, 'Internal error'));
    }
  };
}

// ---- router.js ----
// Scripted fallback brain. Works with no AI key and no network.
// parseIntent() is pure; runScripted() calls the planner tools and writes the reply in the bunny's voice.

const MOODS = ['idle', 'listening', 'thinking', 'happy', 'excited', 'confused', 'concerned', 'encouraging', 'celebrating', 'sleepy'];

const MAX_ITEMS = 5;

function extractMinutes(text) {
  let out = text;
  let minutes = null;
  const hr = out.match(/\b(?:for\s+|about\s+|around\s+)?(\d+(?:\.\d+)?)\s*(?:hours?|hrs?|h)\b/i);
  if (hr) {
    minutes = Math.round(parseFloat(hr[1]) * 60);
    out = out.replace(hr[0], ' ');
  }
  const mn = out.match(/\b(?:for\s+|about\s+|around\s+)?(\d+)\s*(?:minutes?|mins?|m)\b/i);
  if (mn) {
    minutes = (minutes || 0) + parseInt(mn[1], 10);
    out = out.replace(mn[0], ' ');
  }
  if (minutes === null) {
    const half = out.match(/\b(?:for\s+)?half an hour\b/i);
    const one = out.match(/\b(?:for\s+)?an hour\b/i);
    if (half) {
      minutes = 30;
      out = out.replace(half[0], ' ');
    } else if (one) {
      minutes = 60;
      out = out.replace(one[0], ' ');
    }
  }
  return { minutes, text: out.replace(/\s+/g, ' ').trim() };
}

function cleanTitle(s) {
  s = s.replace(/^["'\u201c\u2018\s]+|["'\u201d\u2019\s.!?]+$/g, '');
  s = s.replace(/\s+(?:to|on|in|for)\s+(?:my\s+)?(?:list|plan|todo|to-do|day|today|schedule)$/i, '');
  s = s.replace(/^(?:a\s+)?(?:new\s+)?task[:\s]+/i, '');
  s = s.trim();
  return s ? s[0].toUpperCase() + s.slice(1) : s;
}

function parseStart(l) {
  const m = l.match(/\b(?:start(?:ing)?(?:\s+at)?|from|at)\s+(\d{1,2})(?::(\d{2}))?\s*(am|pm)?\b/);
  if (!m) return undefined;
  let h = parseInt(m[1], 10);
  const min = m[2] ? parseInt(m[2], 10) : 0;
  if (m[3] === 'pm' && h < 12) h += 12;
  if (m[3] === 'am' && h === 12) h = 0;
  if (h > 23 || min > 59) return undefined;
  return String(h).padStart(2, '0') + ':' + String(min).padStart(2, '0');
}

function parseIntent(raw) {
  const s = String(raw).trim().replace(/\s+/g, ' ');
  const l = s.toLowerCase();
  let m;

  if (/^(help|commands?)\b/.test(l) || /\bwhat can you do\b/.test(l) || /\bhow (do|does) (this|it|you) work\b/.test(l)) return { intent: 'help' };
  if (/\bstreak\b|\bhow many days\b|\bin a row\b/.test(l)) return { intent: 'streak' };

  // complete: by id ("done #3"), "mark X as done", "finished X", or bare "done"
  if ((m = l.match(/(?:#|\btask\s+)(\d+)/)) && /\b(done|finish(?:ed)?|complete(?:d)?|did|check(?:ed)? off|mark)\b/.test(l)) {
    return { intent: 'complete', id: parseInt(m[1], 10) };
  }
  if ((m = s.match(/^mark\s+(?:the\s+|my\s+)?(.+?)\s+(?:as\s+)?(?:done|complete(?:d)?)[.!]*$/i))) {
    return { intent: 'complete', title: cleanTitle(m[1]) };
  }
  if (/^(done|finished|completed)[.!]*$/.test(l)) return { intent: 'complete', ask: true };
  if ((m = s.match(/^(?:i(?:'ve| have)?\s+)?(?:just\s+)?(?:finished|finish|completed|complete|done with|done|did|checked off|check off|ticked off|tick off)\s+(?!you\b|we\b|i\b)(?:with\s+)?(?:the\s+|my\s+)?(.+?)(?:\s+as done)?[.!]*$/i))) {
    return { intent: 'complete', title: cleanTitle(m[1]) };
  }

  // add
  if ((m = s.match(/^(?:(?:can|could) you\s+)?(?:please\s+|pls\s+)?(?:add|put|remind me to|i need to|i have to|i must|i should|i want to|todo|task)(?::|\s)\s*(.+)$/i))) {
    const rest = m[1].trim();
    if (/^(?:my\s+|the\s+)?(?:day|today|schedule|plan)$/i.test(rest)) return { intent: 'plan', start: parseStart(l) };
    const parts = rest.split(/[;,]/).map((x) => x.trim()).filter(Boolean);
    const items = [];
    for (const part of parts) {
      const { minutes, text } = extractMinutes(part);
      const title = cleanTitle(text);
      if (!title || /^(?:a\s+|some\s+|\d+\s+)?tasks?$/i.test(title)) continue;
      items.push(minutes === null ? { title } : { title, minutes });
    }
    if (!items.length) return { intent: 'add_ask' };
    return { intent: 'add', items: items.slice(0, MAX_ITEMS), truncated: items.length > MAX_ITEMS };
  }

  if (/\b(plan|agenda|schedule|my day|today'?s list|to-?do list|what(?:'s| is)(?: on)?(?: my)? (?:plan|list|today|agenda)|what do i have|what should i do)\b/.test(l)) {
    return { intent: 'plan', start: parseStart(l) };
  }
  if (/\b(tired|sleepy|exhausted|good ?night|going to (?:bed|sleep)|bedtime)\b/.test(l)) return { intent: 'tired' };
  if (/^(hi|hello|hey|hiya|yo|good (?:morning|afternoon|evening))\b/.test(l)) return { intent: 'greeting' };
  if (/\b(thanks|thank you|thx)\b/.test(l)) return { intent: 'thanks' };
  return { intent: 'unknown' };
}

const plural = (n, w) => `${n} ${w}${n === 1 ? '' : 's'}`;
const EXAMPLES = 'Try "add read chapter 3 for 45 min", "plan my day", "finished read chapter" or "how is my streak?"';

const toolFailure = (res) => ({ reply: `Hmm, ${lowerFirst(res.structuredContent?.error || 'something went wrong')}`, mood: 'confused' });
const lowerFirst = (t) => (t ? t[0].toLowerCase() + t.slice(1) : t);

// callTool(name, args) -> MCP tool result ({content, structuredContent, isError})
async function runScripted(message, callTool) {
  const p = parseIntent(message);
  switch (p.intent) {
    case 'help':
      return { reply: `I'm your planner bunny. I can add tasks, build your day, mark things done and track your streak. ${EXAMPLES}.`, mood: 'encouraging' };
    case 'greeting':
      return { reply: 'Hi there! Ready to plan your day? Tell me what you would like to get done.', mood: 'happy' };
    case 'thanks':
      return { reply: 'Any time! I am happy to help.', mood: 'happy' };
    case 'tired':
      return { reply: 'Rest well. Your list is safe with me, and we can pick it up tomorrow.', mood: 'sleepy' };
    case 'add_ask':
      return { reply: 'What would you like to add? For example: "add study math for 45 min".', mood: 'listening' };
    case 'unknown':
      return { reply: `I'm in offline mode right now, so I only know planning. ${EXAMPLES}.`, mood: 'confused' };

    case 'add': {
      const done = [];
      let last = null;
      for (const it of p.items) {
        const r = await callTool('add_task', it);
        if (r.isError) {
          if (!done.length) return toolFailure(r);
          return { reply: `Added ${done.join(', ')}, but "${it.title}" didn't work: ${lowerFirst(r.structuredContent.error)}`, mood: 'confused' };
        }
        done.push(`"${r.structuredContent.task.title}"`);
        last = r.structuredContent;
      }
      const head = done.length === 1 ? `Got it! ${done[0]} is on your list (${last.task.minutes} min).` : `Got it! Added ${done.join(', ')}.`;
      const tail = last.overbooked
        ? ` That is ${plural(last.openCount, 'open task')} (${last.totalMinutes} min), which is a lot for one day. Want me to plan it and suggest what to move?`
        : ` ${plural(last.openCount, 'open task')} today.`;
      return { reply: head + (p.truncated ? ` (I took the first ${MAX_ITEMS}.)` : '') + tail, mood: last.mood, data: last };
    }

    case 'complete': {
      if (p.ask) return { reply: 'Which task did you finish? Tell me its name or its #id.', mood: 'listening' };
      const r = await callTool('complete_task', p.id !== undefined ? { id: p.id } : { title: p.title });
      if (r.isError) return toolFailure(r);
      const d = r.structuredContent;
      const tail = d.dayCleared ? ' Your day is clear!' : ` ${d.openCount} to go.`;
      return { reply: `Nice work! "${d.task.title}" is done.${tail} Streak: ${plural(d.streak, 'day')}.`, mood: d.mood, data: d };
    }

    case 'plan': {
      const r = await callTool('plan_day', p.start ? { start: p.start } : {});
      if (r.isError) return toolFailure(r);
      const d = r.structuredContent;
      if (!d.schedule.length) return { reply: 'Your plan is empty. Tell me something to add, like "add study math for 45 min".', mood: d.mood, data: d };
      const lines = d.schedule.map((x) => `${x.start}-${x.end}  ${x.title}`).join('\n');
      let reply = `Here is your day:\n${lines}`;
      if (d.overbooked) {
        const titles = d.moveIds.map((id) => d.schedule.find((x) => x.id === id)?.title).filter(Boolean);
        reply += `\n\nThis looks overbooked. I would move ${titles.length ? titles.map((t) => `"${t}"`).join(' and ') : 'a task'} to tomorrow.`;
      }
      return { reply, mood: d.mood, data: d };
    }

    case 'streak': {
      const r = await callTool('get_streak', {});
      if (r.isError) return toolFailure(r);
      return { reply: r.content[0].text, mood: r.structuredContent.mood, data: r.structuredContent };
    }
  }
  return { reply: `I'm in offline mode right now, so I only know planning. ${EXAMPLES}.`, mood: 'confused' };
}

// ---- providers.js ----
// AI provider chain. A provider is:
//   { name: 'gemini',
//     available(env) -> boolean            // e.g. true only when its secret key exists
//     run({ message, callTool, env }) -> Promise<{ reply, mood, toolCalls? } | null> }
// If a provider returns null, throws, or times out, /chat quietly falls back to the scripted router.
//
// STATUS: no AI provider is implemented yet, so the chain is empty and every request uses the
// scripted router. A Gemini adapter is planned as the next step; it must be written against the
// current Gemini docs and tested with a real key before it is added here.
function buildProviders(_env) {
  return [];
}

// ---- chat.js ----
// POST /chat  { "message": "add gym 30 min" }  ->  { reply, mood, mode, toolCalls, data? }
// Headers: x-session-id (anonymous, isolates tasks), x-tz-offset-minutes (client UTC offset).
// Tools are called through the real MCP handler (JSON-RPC tools/call), never by touching storage directly.

const MAX_BODY_CHARS = 4000;
const MAX_MESSAGE_CHARS = 500;
const IP_LIMIT_PER_MIN = 60;
const SESSION_LIMIT_PER_MIN = 20;

// Best-effort limiter. On Workers each isolate has its own memory, so this slows abuse
// but is not a hard guarantee.
class RateLimiter {
  constructor({ windowMs = 60000, now = () => Date.now(), maxKeys = 5000 } = {}) {
    this.windowMs = windowMs;
    this.now = now;
    this.maxKeys = maxKeys;
    this.hits = new Map();
  }
  // returns null if allowed, otherwise seconds to wait
  check(key, limit) {
    const t = this.now();
    const arr = (this.hits.get(key) || []).filter((x) => t - x < this.windowMs);
    if (arr.length >= limit) {
      this.hits.set(key, arr);
      return Math.max(1, Math.ceil((arr[0] + this.windowMs - t) / 1000));
    }
    arr.push(t);
    this.hits.delete(key);
    this.hits.set(key, arr);
    if (this.hits.size > this.maxKeys) this.hits.delete(this.hits.keys().next().value);
    return null;
  }
}
const defaultLimiter = new RateLimiter();

const withTimeout = (p, ms) =>
  new Promise((resolve, reject) => {
    const t = setTimeout(() => reject(new Error('timeout')), ms);
    p.then(
      (v) => {
        clearTimeout(t);
        resolve(v);
      },
      (e) => {
        clearTimeout(t);
        reject(e);
      },
    );
  });

function createChat({ mcp, providers, limiter = defaultLimiter, providerTimeoutMs = 8000 }) {
  return async function handleChat(request, env = {}) {
    const cors = corsHeaders(request, env);
    const json = (body, status = 200, extra = {}) =>
      new Response(JSON.stringify(body), { status, headers: { 'content-type': 'application/json', ...cors, ...extra } });

    try {
      if (!originAllowed(request, env)) return new Response('Forbidden origin', { status: 403 });
      if (request.method === 'OPTIONS') return new Response(null, { status: 204, headers: cors });
      if (request.method !== 'POST') {
        return new Response('Method Not Allowed', { status: 405, headers: { allow: 'POST, OPTIONS', ...cors } });
      }

      const { sid, tzOffsetMinutes } = sessionInfo(request);
      const ip = request.headers.get('cf-connecting-ip') || 'local';
      const wait = limiter.check('ip:' + ip, IP_LIMIT_PER_MIN) ?? limiter.check('sid:' + sid, SESSION_LIMIT_PER_MIN);
      if (wait !== null) {
        return json(
          { error: 'rate_limited', reply: 'Whoa, that is a lot of messages at once! Give me a moment and try again.', mood: 'confused', mode: 'error' },
          429,
          { 'retry-after': String(wait) },
        );
      }

      const text = await request.text();
      if (text.length > MAX_BODY_CHARS) return json({ error: 'too_large', reply: 'That message is too big for me.', mood: 'confused', mode: 'error' }, 413);
      let body;
      try {
        body = JSON.parse(text);
      } catch {
        return json({ error: 'bad_json', reply: 'I could not read that request.', mood: 'confused', mode: 'error' }, 400);
      }
      const message = body && typeof body.message === 'string' ? body.message.trim() : '';
      if (!message) return json({ error: 'empty_message', reply: 'Say something and I will help!', mood: 'listening', mode: 'error' }, 400);
      if (message.length > MAX_MESSAGE_CHARS) {
        return json({ error: 'message_too_long', reply: `Please keep messages under ${MAX_MESSAGE_CHARS} characters.`, mood: 'confused', mode: 'error' }, 400);
      }

      // In-process MCP client: a real JSON-RPC tools/call against the same /mcp handler.
      const toolCalls = [];
      let rpcId = 1;
      const callTool = async (name, args) => {
        const res = await mcp(
          new Request('http://internal/mcp', {
            method: 'POST',
            headers: { 'content-type': 'application/json', 'x-session-id': sid, 'x-tz-offset-minutes': String(tzOffsetMinutes) },
            body: JSON.stringify({ jsonrpc: '2.0', id: rpcId++, method: 'tools/call', params: { name, arguments: args } }),
          }),
          env,
        );
        const out = await res.json();
        if (out.error) throw new Error('mcp_error ' + out.error.code);
        toolCalls.push({ name, args, isError: !!out.result.isError });
        return out.result;
      };

      let degraded = false;
      for (const p of providers || buildProviders(env)) {
        if (!p.available(env)) continue;
        try {
          const r = await withTimeout(p.run({ message, callTool, env }), providerTimeoutMs);
          if (r && typeof r.reply === 'string' && r.reply) {
            return json({ reply: r.reply, mood: MOODS.includes(r.mood) ? r.mood : 'idle', mode: p.name, toolCalls, data: r.data });
          }
          degraded = true;
        } catch {
          degraded = true;
        }
      }

      const r = await runScripted(message, callTool);
      return json({ reply: r.reply, mood: MOODS.includes(r.mood) ? r.mood : 'idle', mode: 'scripted', degraded, toolCalls, data: r.data });
    } catch {
      // Never leak internals. The front end can still show this reply and a concerned bunny.
      return json(
        { error: 'server_error', reply: 'Oops, my ears got tangled and I could not finish that. Please try again in a moment.', mood: 'concerned', mode: 'error' },
        500,
      );
    }
  };
}

// ---- app.js ----
// Single router for all endpoints: /mcp, /chat, /health.

function createApp({ store, now, providers, limiter, providerTimeoutMs } = {}) {
  const mcp = createMcp({ store, now });
  const chat = createChat({ mcp, providers, limiter, providerTimeoutMs });
  return async function app(request, env = {}) {
    const { pathname } = new URL(request.url);
    if (pathname === '/mcp') return mcp(request, env);
    if (pathname === '/chat') return chat(request, env);
    if (pathname === '/' || pathname === '/health') {
      const ai = (providers || buildProviders(env)).filter((p) => p.available(env)).map((p) => p.name);
      return Response.json({ name: 'bunny-planner', endpoints: { mcp: '/mcp', chat: '/chat' }, transport: 'streamable-http', protocol: '2025-11-25', ai, fallback: 'scripted' });
    }
    return new Response('Not found', { status: 404 });
  };
}


